135	void up_enable_irq(int irq)
136	{
137	  if (irq == RISCV_IRQ_MSOFT)
138	    {
139	      SET_CSR(CSR_MIE, MIE_MSIE);
140	    }
141	  else if (irq == RISCV_IRQ_MTIMER)
142	    {
143	      SET_CSR(CSR_MIE, MIE_MTIE);
144	    }
145	  else if (irq == RISCV_IRQ_MEXT)
146	    {
147	      SET_CSR(CSR_MIE, MIE_MEIE);
148	    }
149	  else
150	    {
151	      int extirq = irq - RISCV_IRQ_ASYNC;
152	
153	      if (irq >= RISCV_IRQ_ASYNC &&
154	          extirq >= 0 && extirq <= D13X_IRQN_LAST)
155	        {
156	          csi_vic_enable_irq(extirq);
157	        }
158	    }
159	}
