164	    {
165	      CLEAR_CSR(CSR_MIE, MIE_MSIE);
166	    }
167	  else if (irq == RISCV_IRQ_MTIMER)
168	    {
169	      CLEAR_CSR(CSR_MIE, MIE_MTIE);
170	    }
171	  else if (irq == RISCV_IRQ_MEXT)
172	    {
173	      CLEAR_CSR(CSR_MIE, MIE_MEIE);
174	    }
175	  else
176	    {
