198	irqstate_t up_irq_enable(void)
199	{
200	  irqstate_t oldstat;
201	
202	  /* Keep machine external interrupts globally reachable. Timer/software
203	   * sources are enabled individually by up_enable_irq().
204	   */
205	
206	  SET_CSR(CSR_MIE, MIE_MEIE);
207	
208	  oldstat = READ_AND_SET_CSR(CSR_MSTATUS, MSTATUS_MIE);
209	  return oldstat;
210	}
