212	void *riscv_dispatch_irq(uintreg_t vector, uintreg_t *regs)
213	{
214	  int irq = (int)(vector & D13X_MCAUSE_CODE_MASK);
215	
216	  if ((vector & RISCV_IRQ_BIT) != 0)
217	    {
218	      irq += RISCV_IRQ_ASYNC;
219	    }
220	
221	  if (irq >= 0 && irq < NR_IRQS)
222	    {
223	      if (irq <= RISCV_MAX_EXCEPTION && regs != NULL)
224	        {
225	          d13x_dump_exception(irq, regs);
226	        }
227	
228	      riscv_ack_irq(irq);
229	      regs = riscv_doirq(irq, regs);
230	    }
231	
232	  return regs;
233	}
