242	static int d13x_uart_interrupt(int irq, void *context, void *arg)
243	{
244	  FAR struct uart_dev_s *dev = arg;
245	  FAR struct d13x_uart_s *priv = dev->priv;
246	  uint32_t iir;
247	  int passes;
248	
249	  (void)irq;
250	  (void)context;
251	
252	  for (passes = 0; passes < 256; passes++)
253	    {
254	      iir = d13x_uart_getreg32(priv->base + D13X_UART_IIR_OFF);
255	      if ((iir & D13X_UART_IIR_NO_INT) != 0 &&
256	          (iir & 0x0fU) != D13X_UART_IIR_BUSY)
257	        {
258	          break;
259	        }
260	
261	      switch (iir & 0x0fU)
262	        {
263	          case D13X_UART_IIR_RECV_DATA:
264	          case D13X_UART_IIR_CHAR_TIMEOUT:
265	            uart_recvchars(dev);
266	            break;
267	
268	          case D13X_UART_IIR_THR_EMPTY:
269	            d13x_uart_putreg32(d13x_uart_getreg32(priv->base +
270	                               D13X_UART_IER_OFF) &
271	                               ~D13X_UART_IER_ETBEI,
272	                               priv->base + D13X_UART_IER_OFF);
273	            break;
274	
275	          case D13X_UART_IIR_RECV_LINE:
276	            (void)d13x_uart_getreg32(priv->base + D13X_UART_LSR_OFF);
277	            uart_recvchars(dev);
278	            break;
279	
280	          case D13X_UART_IIR_BUSY:
281	            (void)d13x_uart_getreg32(priv->base + D13X_UART_USR_OFF);
282	            break;
283	
284	          default:
285	            (void)d13x_uart_getreg32(priv->base + D13X_UART_LSR_OFF);
286	            break;
287	        }
288	    }
289	
290	  return OK;
291	}
